'use strict';
const $=s=>document.querySelector(s),M=StudioModel;
let project={version:1,name:'Untitled news sequence',width:1920,height:1080,duration:12,layers:[]};
let lastBrowserSearch=0,previewScale=1,stateMapId=null,mapEditor=null,mapEditorLayer=null,mapEditorInitial=null,clipboardLayers=[],drawingStroke=null,drawMode=false;
let selected=new Set(),time=0,playing=false,exporting=false,tab='graphics',lastFrame=0,history=[],future=[],drag=null,audioContext=null,destination=null,exportAudio=false,exportFrameTrack=null;
const maps=new Map(),media=new Map(),cache=new Map();const canvas=$('#canvas'),ctx=canvas.getContext('2d');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={text:'#366d59',caption:'#46735d',logo:'#66629b',audio:'#866238',video:'#376f90',image:'#526992',map:'#3d646b',geometry:'#776040',rings:'#a25850',shape:'#656080',marker:'#8b6845'};
const status=s=>$('#status').textContent=s;
function checkpoint(){history.push(JSON.stringify(project));if(history.length>40)history.shift();future=[];}
function applySnapshot(s){try{project=M.validate(JSON.parse(s));selected.clear();time=0;dispose();refresh();}catch(e){status(e.message);}}
function undo(){if(exporting)return;if(history.length){future.push(JSON.stringify(project));applySnapshot(history.pop());}}
function redo(){if(exporting)return;if(future.length){history.push(JSON.stringify(project));applySnapshot(future.pop());}}
function dispose(){maps.forEach(m=>m.remove());maps.clear();media.forEach(v=>v.pause?.());media.clear();$('#mapHost').replaceChildren();}
function choose(id,multi=false){if(drawMode&&project.layers.find(l=>l.id===id)?.fx!=='freehand'){drawMode=false;drawingStroke=null;canvas.style.cursor='default';}if(!multi)selected.clear();if(multi&&selected.has(id))selected.delete(id);else selected.add(id);renderLayers();renderTracks();renderInspector();if($('#navigate').checked&&!stateMapId&&current()?.type!=='map')setNavigation(false);layoutMaps();}
function add(type,name,extra={}){checkpoint();const l=M.layer(type,name,{duration:project.duration,...extra});if((['marker','geometry','rings'].includes(type)&&extra.lng!=null)||type==='geometry')l.mapId=extra.mapId||(current()?.type==='map'?current().id:project.layers.find(x=>x.type==='map')?.id);if(type==='map'){const i=project.layers.findIndex(x=>x.type==='map');project.layers.splice(i<0?project.layers.length:i,0,l);}else project.layers.unshift(l);selected=new Set([l.id]);playing=false;$('#play').textContent='▶ Play';time=Math.min(project.duration-.01,Math.max(.8,l.start+.8));refresh();return l;}
function current(){return project.layers.find(l=>selected.has(l.id));}
function refresh(){canvas.width=project.width;canvas.height=project.height;$('#stage').style.aspectRatio=`${project.width}/${project.height}`;$('#projectName').value=project.name;$('#sequenceDuration').value=project.duration;$('#scrub').max=project.duration;$('#durationDisplay').textContent=project.duration.toFixed(2)+'s';$('#format').value=`${project.width},${project.height}`;renderLayers();renderTracks();renderInspector();syncMaps();draw();}
const presets=[
 ['graphics','text','Headline','Editable title with independent timing.'],['graphics','caption','Caption','Subtitles on their own editable layer.'],['graphics','logo','Brand mark','Text logo; import an image for your real logo.'],['graphics','shape','Warning banner','Color, size, timing, and motion controls.'],['graphics','shape','Arrow','Independent direction and size.'],['graphics','rings','Earthquake rings','Independent ring spacing, reach, and line weight.'],['graphics','template','Breaking news sequence','Headline, banner, caption, and logo — separate layers.'],
 ['maps','mapstyle','Satellite zoom','Real surface imagery with a camera zoom.'],['maps','mapstyle','Country zoom','Smooth country-to-region camera sequence.'],['maps','mapstyle','City locator rings','Street map, geographic pin, and separate illustrative rings.'],['maps','mapstyle','Street-level locator','Detailed street view with location search.'],['maps','mapstyle','Region shading','Separate editable boundaries with independent colors.'],['maps','mapstyle','Politics / election layout','Separate map, title, legend, and sourced area highlights.'],['maps','map','Geographic map','Street, satellite basemap, or dated weather imagery.'],['maps','sequence','Earth → city','Editable camera keyframes with smooth easing.'],['maps','route','Travel route','Geographic line between two coordinates.'],['maps','marker','Location marker','Standalone geographic label and pin.'],['maps','geojson','Import boundaries','Countries, states, counties, tracks, or cones.'],
 ['weather','alerts','NWS warning boundaries','Fetch current official US warning polygons.'],['weather','earthquake','USGS earthquake','Choose an event; create separate rings, pin, and labels.'],['weather','hurricane','Hurricane advisory layout','Blank editable information panel and separate track/cone imports.'],['weather','map','Weather satellite','NASA dated true-color imagery, distinct from basemap.'],['weather','geojson','Import forecast data','Import sourced GeoJSON forecasts as individual layers.']
];
function presetArtwork(p){const type=p[1],name=p[2];let art;if(type==='rings')art='<svg viewBox="0 0 200 70"><circle cx="100" cy="35" r="3" fill="#ff766a"/><g class="miniRings" fill="none" stroke="#ff766a"><circle cx="100" cy="35" r="12"/><circle cx="100" cy="35" r="23"/><circle cx="100" cy="35" r="34"/></g></svg>';else if(type==='logo')art='<b class="miniLogo">RAWS</b>';else if(type==='caption')art='<b class="miniCaption">Your spoken-word caption</b>';else if(name==='Arrow')art='<b class="miniArrow">➜</b>';else if(type==='shape')art='<b class="miniWarning">⚠ WEATHER WARNING</b>';else if(type==='template')art='<b class="miniHeadline">YOUR HEADLINE</b><i></i><span class="miniBadge">RAWS</span>';else if(p[0]==='maps'||['map','alerts','hurricane','geojson'].includes(type))art='<canvas class="mapStylePreview" width="240" height="135" data-map-style="'+esc(name)+'"></canvas>';else if(p[0]==='weather')art='<b>☁</b><span class="miniMapLabel">'+esc(name)+'</span>';else art='<b class="miniHeadline">YOUR HEADLINE</b>';return `<span class="presetPreview ${p[0]} ${type}" aria-hidden="true">${art}</span>`;}
for(const p of StudioFX.catalog)presets.push([p[0]==='weather'?'weather':'graphics','fx:'+p[2],p[1],p[3]]);
function renderTools(){const q=$('#presetSearch').value.toLowerCase();$('#tools').innerHTML=presets.filter(p=>(q||$('#fxCategory').value!=='all'||p[0]===tab)&&(!q||p.join(' ').toLowerCase().includes(q))&&($('#fxCategory').value==='all'||StudioFX.catalog.some(f=>p[1]==='fx:'+f[2]&&f[0]===$('#fxCategory').value))).map(p=>`<button class="tool" data-tool="${esc(p[1])}" data-name="${esc(p[2])}">${p[1].startsWith('fx:')?`<canvas class="fxPreview" width="240" height="135" data-fx="${esc(p[1].slice(3))}"></canvas>`:presetArtwork(p)}<strong>＋ ${esc(p[2])}</strong><small>${esc(p[3])}</small></button>`).join('');$('#tools').querySelectorAll('button').forEach(b=>{b.draggable=true;b.ondragstart=e=>e.dataTransfer.setData('application/x-raws-preset',JSON.stringify({type:b.dataset.tool,name:b.dataset.name}));b.onclick=()=>{const before=project.layers.length;tool(b.dataset.tool,b.dataset.name);if(['map','mapstyle','sequence'].includes(b.dataset.tool))openMapWorkspace(false);else if(project.layers.length>before&&(['text','caption','logo','shape','rings','template','hurricane'].includes(b.dataset.tool)||b.dataset.tool.startsWith('fx:'))&&!drawMode)previewSelectedMotion();};});}
function tool(type,name){
 if(exporting)return;
 if(type.startsWith('fx:')){addEffect(type.slice(3));return;}
 if(type==='mapstyle'){mapStylePreset(name);return;}
 if(type==='map'){addMap(name);return;}
 if(type==='sequence'){let l=project.layers.find(l=>l.type==='map');if(!l)l=addMap('Globe → city');checkpoint();l.projection='globe';l.cameraPreset=true;l.keys=[{time:0,lng:l.lng,lat:l.lat,zoom:0},{time:project.duration*.55,lng:l.lng,lat:l.lat,zoom:3},{time:project.duration,lng:l.lng,lat:l.lat,zoom:10}];choose(l.id);syncMaps();status('Earth → city camera sequence created. Edit or add keyframes in the map inspector.');return;}
 if(type==='geojson'){ $('#mediaInput').click();return;}
 if(type==='alerts'){loadAlerts();return;}
 if(type==='earthquake'){loadQuakes();return;}
 if(type==='rings'){openQuakeMaker();return;}
 if(type==='marker'&&!project.layers.some(l=>l.type==='map'))addMap();
 if(type==='route'){const a=prompt('Start latitude, longitude','40.71, -74.00');if(!a)return;const b=prompt('End latitude, longitude','51.50, -0.12');if(!b)return;const aa=parseCoords(a),bb=parseCoords(b);if(!aa||!bb){status('Enter valid latitude, longitude pairs.');return;}if(!project.layers.some(l=>l.type==='map'))addMap();add('geometry','Travel route',{geojson:{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:[[aa.lng,aa.lat],[bb.lng,bb.lat]]}},color:'#9af0c4',lineWidth:5,source:'User-defined route · illustrative',reveal:true});return;}
 if(type==='template'){add('shape','Breaking banner',{x:80,y:760,w:440,h:86,color:'#b5283d',text:'BREAKING NEWS',fontSize:38});add('text','Headline',{x:80,y:860,w:1700,h:120,text:'Your verified headline goes here',fontSize:64});add('caption','Caption',{x:300,y:690,w:1300,h:80,text:'Add your spoken-word caption',fontSize:36});add('logo','Raws Reports',{x:1650,y:60,w:200,h:75,text:'RAWS',fontSize:38,color:'#9af0c4'});return;}
 if(type==='hurricane'){if(!project.layers.some(l=>l.type==='map'))addMap('Hurricane map');add('shape','Storm information panel',{x:80,y:100,w:620,h:440,color:'#17283d',text:'',fontSize:30});add('text','Storm name',{x:115,y:135,w:530,h:90,text:'STORM NAME — ENTER ADVISORY',fontSize:36});['Category','Wind','Pressure','Movement','Issued'].forEach((field,i)=>add('text','Advisory '+field,{x:115,y:250+i*48,w:500,h:45,text:field+': —',fontSize:29}));add('text','Advisory source',{x:90,y:990,w:1650,h:50,text:'Layout only · Import official track / cone GeoJSON with source and issue time',fontSize:24});status('Hurricane layout loaded. Official cone and track must be imported separately; no forecast is fabricated.');return;}
 const extra=type==='rings'?{x:project.width/2,y:project.height/2,w:500,h:500,rings:6,spacing:45,radius:20,reach:430,lineWidth:2,speed:90,delay:.2,fade:true,loop:true,pulse:'smooth',color:'#ff766a',animation:'none'}:type==='shape'?{x:100,y:150,w:name==='Arrow'?400:680,h:100,color:'#bc354d',text:name==='Arrow'?'':'WARNING',shape:name==='Arrow'?'arrow':'rectangle',angle:0,fontSize:42}:type==='marker'?{x:0,y:0,w:180,h:90,lng:-98,lat:39,markerSize:9,text:'Location',fontSize:24}:type==='caption'?{x:280,y:920,w:1360,h:100,text:'Add your caption here',fontSize:42}:type==='logo'?{x:1640,y:70,w:200,h:90,text:'RAWS',color:'#9af0c4',fontSize:46}:{};
 add(type,name,extra);
}
function addMap(name='Geographic map'){return add('map',name,{x:0,y:0,w:project.width,h:project.height,lng:-98,lat:39,zoom:3,bearing:0,pitch:0,projection:'mercator',basemap:name==='Weather satellite'?'weather':'satellite',date:new Date(Date.now()-86400000).toISOString().slice(0,10),keys:[],animation:'none'});}
function renderLayers(){ $('#layerCount').textContent=project.layers.length;$('#layerList').innerHTML=project.layers.map(l=>`<div class="layer ${selected.has(l.id)?'selected':''}" draggable="true" data-id="${esc(l.id)}"><em>${esc(l.type.slice(0,3))}</em><span>${esc(l.name)}${l.group?' / '+esc(l.group):''}</span><button data-act="visible" title="Visibility">${l.visible?'◉':'○'}</button><button data-act="locked" title="Lock">${l.locked?'▣':'□'}</button></div>`).join('');$('#layerList').querySelectorAll('.layer').forEach(el=>{el.onclick=e=>{if(exporting)return;const l=project.layers.find(l=>l.id===el.dataset.id);if(e.target.dataset.act){checkpoint();l[e.target.dataset.act]=!l[e.target.dataset.act];refresh();}else choose(l.id,e.shiftKey);};el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.id);};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(exporting)return;const id=e.dataTransfer.getData('text/plain'),a=project.layers.findIndex(l=>l.id===id),b=project.layers.findIndex(l=>l.id===el.dataset.id);if(a<0||b<0||a===b||project.layers[a].locked)return;checkpoint();const [l]=project.layers.splice(a,1);project.layers.splice(b,0,l);refresh();};});}
function timelineWidth(){return Math.max(400,$('#timeline').clientWidth-145)*Number($('#timelineZoom').value);}
function renderTracks(){const w=timelineWidth(),scale=w/project.duration;$('#ruler').style.width=w+'px';$('#ruler').innerHTML=Array.from({length:11},(_,i)=>`<span style="left:${i*w/10}px">${(project.duration*i/10).toFixed(1)}s</span>`).join('');$('#tracks').innerHTML=project.layers.map(l=>`<div class="track"><div class="trackName">${esc(l.name)}</div><div class="lane" style="width:${w}px"><div class="clip ${selected.has(l.id)?'selected':''}" data-id="${esc(l.id)}" style="left:${l.start*scale}px;width:${l.duration*scale}px;background:${colors[l.type]}"><i class="edge" data-edge="start"></i><span>${esc(l.name)}</span><i class="edge" data-edge="end"></i></div><div class="playhead" style="left:${time*scale}px"></div></div></div>`).join('');$('#tracks').querySelectorAll('.clip').forEach(el=>el.onpointerdown=e=>{if(exporting)return;const l=project.layers.find(l=>l.id===el.dataset.id);choose(l.id,e.shiftKey);if(l.locked)return;checkpoint();drag={kind:'timeline',l,edge:e.target.dataset.edge,origin:e.clientX,start:l.start,duration:l.duration,offset:l.offset||0,scale};e.preventDefault();});$('#ruler').onclick=e=>{if(exporting)return;const b=$('#ruler').getBoundingClientRect();seek(M.clamp((e.clientX-b.left)/scale,0,project.duration));};}
function field(label,key,l,type='number',min,max,step){return `<div class="field"><label>${esc(label)}</label><input data-key="${esc(key)}" type="${type}" ${type==='checkbox'?(l[key]?'checked':''):`value="${esc(l[key]??'')}"`} ${min!=null?`min="${min}"`:''} ${max!=null?`max="${max}"`:''} ${step!=null?`step="${step}"`:''} ${l.locked?'disabled':''}></div>`;}
function selectField(label,key,l,items){return `<div class="field"><label>${esc(label)}</label><select data-key="${key}" ${l.locked?'disabled':''}>${items.map(([v,n])=>`<option value="${v}" ${l[key]===v?'selected':''}>${n}</option>`).join('')}</select></div>`;}
function renderInspector(){const l=current();if(!l){$('#properties').innerHTML='<div class="note">Select a layer to edit its timing, appearance, and animation.<br><br>Import your footage, start with a graphics preset, or add a real map.</div>';return;}
 let html=field('Layer name','name',l,'text')+`<div class="note">${esc(l.type.toUpperCase())} · ${selected.size} selected${l.locked?' · LOCKED':''}</div>`;
 html+='<div class="row">'+field('Start (seconds)','start',l,'number',0,project.duration,.01)+field('Duration (seconds)','duration',l,'number',.03,3600,.01)+'</div>';
 if(l.type!=='rings')html+='<div class="divider">TRANSFORM & MOTION</div><div class="row">'+field('X (pixels)','x',l)+field('Y (pixels)','y',l)+field('Width','w',l,'number',1,8000)+field('Height','h',l,'number',1,8000)+'</div>'+field('Opacity','opacity',l,'range',0,1,.01)+selectField('Entrance animation','animation',l,[['none','None'],['fade','Fade in'],['slide','Slide up'],['pulse','Pulse'],['left','Slide from left'],['right','Slide from right'],['pop','Scale reveal'],['wipe','Wipe reveal'],['kenburns','Slow push in']])+field('Animation duration (seconds)','animationDuration',{...l,animationDuration:l.animationDuration||.6},'number',.03,10,.01)+field('Group name (organization only)','group',l,'text');
 if(['text','caption','logo','shape','marker'].includes(l.type)&&!l.src)html+=`<div class="field"><label>Editable text</label><textarea data-key="text" rows="4" ${l.locked?'disabled':''}>${esc(l.text)}</textarea></div>`+field('Font size','fontSize',l,'number',8,300);
 if(!['map','rings'].includes(l.type))html+=field('Color','color',l,'color');
 if(['audio','video'].includes(l.type))html+=field('Source trim / offset (seconds)','offset',l,'number',0,3600,.01)+field('Volume','volume',l,'range',0,2,.01);
 if(['video','image','logo'].includes(l.type)&&l.src)html+='<div class="divider">CROP & FIT</div>'+selectField('Fit inside layer','fit',{...l,fit:l.fit||'contain'},[['contain','Fit — show all'],['cover','Fill — crop to frame'],['stretch','Stretch']])+'<div class="row">'+field('Crop left %','cropLeft',{...l,cropLeft:l.cropLeft||0},'number',0,95,.1)+field('Crop right %','cropRight',{...l,cropRight:l.cropRight||0},'number',0,95,.1)+field('Crop top %','cropTop',{...l,cropTop:l.cropTop||0},'number',0,95,.1)+field('Crop bottom %','cropBottom',{...l,cropBottom:l.cropBottom||0},'number',0,95,.1)+'</div>'+field('Rotation °','rotation',{...l,rotation:l.rotation||0},'number',-180,180,1)+'<button id="resetCrop" class="wide">Reset crop</button>';
 if(l.fx)html+=effectInspector(l);
 if(l.type==='geometry')html+=selectField('Highlight animation','highlightFX',{...l,highlightFX:l.highlightFX||'none'},[['none','None'],['flash','Flashing'],['breathe','Breathing pulse']]);
 if(l.type==='shape')html+=field('Rotation (degrees)','angle',l,'number',-360,360);
 if(l.type==='rings')html+='<button id="openQuakeMaker" class="wide primary">Open earthquake maker</button>';
 if(l.type==='rings')html+='<div class="note">Smooth repeating rings. Open the maker to change the look, spread, or speed. Drag the corner to change spread; the center dot and line thickness stay fixed.</div>';

 if(l.type==='marker'){if(l.lng!=null)html+='<div class="divider">GEOGRAPHIC POSITION</div><div class="row">'+field('Latitude','lat',l,'number',-90,90,.0001)+field('Longitude','lng',l,'number',-180,180,.0001)+'</div>';html+=field('Epicenter / marker size','markerSize',l,'number',1,100);}
 if(l.type==='geometry')html+=field('Highlight cycle seconds','highlightDuration',{...l,highlightDuration:l.highlightDuration||1.2},'number',.2,30,.1)+field('Area fill opacity','fillOpacity',{...l,fillOpacity:l.fillOpacity??.24},'range',0,1,.01)+'<div class="divider">GEOGRAPHIC GRAPHIC</div>'+field('Line thickness','lineWidth',l,'number',.5,30,.5)+field('Animated reveal','reveal',l,'checkbox')+field('Source / attribution','source',l,'text')+field('Issue / event time (UTC)','issued',l,'text');
 if(l.type==='map')html+=mapInspector(l);
 html+='<div class="divider">REUSABLE PRESETS</div><button id="saveLayerPreset" class="wide">Save selected layer as preset</button><button id="applyLayerPreset" class="wide">Apply saved preset to this layer</button>'; 
 if(l.source&&l.type!=='geometry')html+=`<div class="note">${esc(l.source)}${l.issued?'<br>'+esc(l.issued):''}</div>`;
 $('#properties').innerHTML=html;
 $('#properties').querySelectorAll('[data-key]').forEach(el=>{el.onchange=()=>{if(exporting||l.locked)return;checkpoint();const key=el.dataset.key;let val=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'?Number(el.value):el.value;if(typeof val==='number'){if(!Number.isFinite(val))return;if(el.min!=='')val=Math.max(Number(el.min),val);if(el.max!=='')val=Math.min(Number(el.max),val);}l[key]=val;if(l.type==='map'&&['lng','lat','zoom','pitch','bearing'].includes(key))l.keys=[];refresh();};});
 if(l.type==='map')bindMapInspector(l);if($('#openQuakeMaker'))$('#openQuakeMaker').onclick=()=>openQuakeMaker(l);
 if($('#resetCrop'))$('#resetCrop').onclick=()=>{if(l.locked||exporting)return;checkpoint();Object.assign(l,{cropLeft:0,cropRight:0,cropTop:0,cropBottom:0});refresh();};
 $('#saveLayerPreset').onclick=()=>{const name=prompt('Preset name',l.name);if(!name)return;const all=JSON.parse(localStorage.getItem('raws.presets')||'{}');const p=structuredClone(l);delete p.src;delete p.geojson;delete p.id;all[name]=p;localStorage.setItem('raws.presets',JSON.stringify(all));status('Preset saved: '+name);};
 $('#applyLayerPreset').onclick=()=>{if(l.locked||exporting)return;const all=JSON.parse(localStorage.getItem('raws.presets')||'{}'),names=Object.keys(all).filter(n=>all[n].type===l.type);if(!names.length){status('No saved presets for this layer type.');return;}const name=prompt('Choose preset by name: '+names.join(', '),names[0]);if(!name||!all[name]||all[name].type!==l.type)return;checkpoint();const keep={id:l.id,src:l.src,geojson:l.geojson};Object.assign(l,structuredClone(all[name]),keep);refresh();status('Applied preset: '+name);};
}
function mapInspector(l){return '<div class="divider">MAP STYLE</div>'+selectField('Map look','look',{...l,look:l.look||'natural'},[['natural','Natural'],['dark','Dark editorial'],['contrast','High contrast']])+field('High-resolution zoom','zoom',l,'range',0,18,.1)+'<div class="divider">MAP & GEOGRAPHY</div>'+selectField('Imagery source','basemap',l,[['street','Geographic street map (OSM)'],['satellite','Satellite basemap (Esri terrain detail)'],['weather','Weather satellite (NASA daily clouds)']])+field('Weather imagery date (UTC)','date',l,'date')+'<div class="note">Satellite basemap: geographic surface detail, without a weather timestamp. NASA weather imagery: dated daily true-color composite; not a real-time GOES loop. Blank tiles may mean imagery is unavailable.</div>'+selectField('Projection','projection',l,[['mercator','Flat map'],['globe','Globe']])+'<div class="row">'+field('Latitude','lat',l,'number',-85,85,.001)+field('Longitude','lng',l,'number',-180,180,.001)+field('Pitch','pitch',{...l,pitch:l.pitch||0},'number',0,60,1)+field('Bearing','bearing',l,'number',-180,180,.1)+'</div><div class="field"><label>Search city, state, county, ZIP, or lat/lon</label><input id="locationSearch" placeholder="Pensacola, FL or 30.42, -87.22"><button id="findLocation" class="wide">Search location</button><div id="results"></div></div>'+(l.selectedLocation?'<button id="selectedMarker" class="wide">Add selected location marker</button><button id="selectedBoundary" class="wide">Highlight selected boundary</button>':'')+'<button id="viewUS" class="wide">Full United States</button><button id="viewEarth" class="wide">Earth view</button><button id="addCamera" class="wide">Capture camera keyframe at playhead</button><button id="clearCamera" class="wide">Clear camera animation</button><div class="note">'+(l.keys?.length?l.keys.map(k=>`${k.time.toFixed(2)}s · zoom ${k.zoom.toFixed(1)} · ${k.lat.toFixed(2)}, ${k.lng.toFixed(2)}`).join('<br>'):'No camera keyframes. Enable Navigate map to pan and zoom.')+'</div><div class="hint">Search is submitted manually and cached. Search results include available regional details. Boundary highlights become individually editable layers.</div>';}
function parseCoords(q){const m=q.trim().match(/^(-?\d+(?:\.\d+)?)\s*[, ]\s*(-?\d+(?:\.\d+)?)$/);if(!m)return null;const lat=Number(m[1]),lng=Number(m[2]);return Math.abs(lat)<=90&&Math.abs(lng)<=180?{lat,lng}:null;}
async function fetchJSON(url){const cached=url.includes('nominatim.openstreetmap.org');if(cached&&cache.has(url))return cache.get(url);if(cached&&!window.desktop){const wait=Math.max(0,1100-(Date.now()-lastBrowserSearch));lastBrowserSearch=Date.now()+wait;if(wait)await new Promise(r=>setTimeout(r,wait));}const v=window.desktop?await desktop.fetchJSON(url):await fetch(url).then(r=>{if(!r.ok)throw Error(`Service unavailable (${r.status})`);return r.json();});if(cached)cache.set(url,v);return v;}
