async function loadAlerts(){try{status('Fetching official NWS active warnings…');if(!project.layers.some(l=>l.type==='map'))addMap('Warnings map');const data=await fetchJSON('https://api.weather.gov/alerts/active?status=actual&message_type=alert');const warnings=data.features.filter(f=>f.geometry&&/Warning/.test(f.properties?.event||''));let count=0;for(const f of warnings.slice(0,60)){add('geometry',f.properties.event+' · '+f.properties.areaDesc,{geojson:f,color:/Tornado|Extreme Wind/.test(f.properties.event)?'#ff4766':'#ffa944',lineWidth:3,source:'NOAA / National Weather Service · '+f.properties.event,issued:f.properties.sent});count++;}status(`Imported ${count} official warning polygons; ${data.features.filter(f=>!f.geometry).length} alerts have no direct polygon. ${warnings.length>60?'First 60 imported.':''}`);}catch(e){status('NWS data unavailable: '+e.message);}}
