const mapCardPaths=[];
function drawMapCards(now){if(!mapCardPaths.length){for(const f of StudioStates.features){if(['AK','HI','PR','GU','AS','MP','VI'].includes(f.properties.STUSPS))continue;const path=new Path2D(),polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;for(const poly of polys)for(const ring of poly){ring.forEach((p,i)=>{const x=(p[0]+126)/60*240,y=135-(p[1]-24)/26*135;i?path.lineTo(x,y):path.moveTo(x,y);});path.closePath();}mapCardPaths.push({code:f.properties.STUSPS,path});}}for(const c of document.querySelectorAll('.mapStylePreview')){const b=c.getBoundingClientRect();if(b.bottom<0||b.top>innerHeight)continue;const x=c.getContext('2d'),w=c.width,h=c.height,name=c.dataset.mapStyle;x.clearRect(0,0,w,h);x.fillStyle='#101e2a';x.fillRect(0,0,w,h);const live=[...maps].map(([id,m])=>({m,l:project.layers.find(l=>l.id===id)})).find(p=>p.l?.basemap==='satellite'&&p.m.loaded());if(live&&name==='Satellite zoom'){x.drawImage(live.m.getCanvas(),0,0,w,h);}else{x.save();const zoom=name.includes('zoom')?1+.35*(.5-.5*Math.cos(now/1000)):1;x.translate(w/2,h/2);x.scale(zoom,zoom);x.translate(-w/2,-h/2);for(const f of mapCardPaths){x.fillStyle=f.code==='FL'&&(/shading|Politics|warning|forecast/.test(name))?'#ce415488':'#1d3947';x.fill(f.path,'evenodd');x.strokeStyle='#86b6be';x.lineWidth=.35;x.stroke(f.path);}x.restore();}if(/locator|location|city/i.test(name)){x.strokeStyle='#9af0c4';x.beginPath();x.arc(w*.65,h*.6,4+12*((now/1000)%1),0,Math.PI*2);x.stroke();}x.fillStyle='#07101ddd';x.fillRect(0,h-17,w,17);x.fillStyle='#bce6d6';x.font='9px sans-serif';x.fillText(name==='Satellite zoom'&&live?'SATELLITE STYLE PREVIEW':'GEOGRAPHIC STYLE PREVIEW',6,h-5);}}

function effectInspector(l){let h='<div class="divider">GRAPHIC EFFECT</div>';if(['gauge','hail','flood','surge','shelter','hospital','closed','blocked','threat','windthreat','evaczone','floodzone','dangerzone','evacroute','closedroute'].includes(l.fx))h+=field('Effect label','label',l,'text');if(l.fx==='gauge')h+=field('Units','subtitle',l,'text')+field('Gauge maximum','fxMax',l,'number',1,10000);if(['gauge','threat','windthreat'].includes(l.fx))h+=field('Show entered value / selected level','fxHasValue',l,'checkbox')+field(l.fx==='gauge'?'Numeric value':'Selected level (0–3)','fxValue',l,'number',0,l.fx==='gauge'?10000:3,l.fx==='gauge'?.1:1);if(l.fx!=='panel')h+=field('Effect duration (seconds)','fxDuration',l,'number',.1,30,.1)+field('Loop animation','fxLoop',l,'checkbox');if(['arrow','route','freehand','circle','underline','brackets','outline','flash','breathe','scan','focus','burst','sparks','glow','wind','lightning','evacroute','closedroute'].includes(l.fx))h+=field('Stroke width','lineWidth',l,'number',1,40,.5);if(['burst','sparks','lightning','shine','glow'].includes(l.fx))h+=field('Glow strength','fxGlow',l,'number',0,80);return h+field('Source / graphic credit','source',l,'text');}

function ringAnchor(l){const p=l.lng!=null?projected(l,l.lng,l.lat):{x:0,y:0};return p?{x:p.x+l.x,y:p.y+l.y}:null;}
function openQuakeMaker(existing=null){if(exporting||existing?.locked)return;if(existing&&project.layers.some(l=>[existing.epicenterId,existing.magnitudeId].includes(l.id)&&l.locked)){status('Unlock the linked marker and magnitude before using the earthquake maker.');return;}playing=false;$('#play').textContent='▶ Play';synchronizeMedia();const marker=existing&&project.layers.find(l=>l.type==='marker'&&l.id===existing.epicenterId);const label=existing&&project.layers.find(l=>l.id===existing.magnitudeId);StudioQuake.open({...existing,start:existing?.start??Math.min(time,project.duration-.5),duration:existing?.duration??Math.max(.5,project.duration-time),markerSize:marker?.markerSize??9,magnitude:label?.text??'',projectWidth:project.width,projectHeight:project.height},v=>{checkpoint();let rings=existing;const group=existing?.group||'Earthquake '+Math.random().toString(36).slice(2,6);const geo=existing?.lng!=null?{lng:existing.lng,lat:existing.lat,mapId:existing.mapId}:{};if(!rings){rings=M.layer('rings','Illustrative earthquake rings',{x:project.width/2,y:project.height/2,w:500,h:500,group});project.layers.unshift(rings);}Object.assign(rings,v,{group,animation:'none',source:''});delete rings.markerSize;delete rings.magnitude;delete rings.projectWidth;delete rings.projectHeight;let pin=marker;if(!pin){pin=M.layer('marker','Epicenter marker',{...geo,x:rings.x,y:rings.y,w:120,h:80,text:'',group,animation:'none'});project.layers.unshift(pin);rings.epicenterId=pin.id;}Object.assign(pin,{markerSize:v.markerSize,color:v.color,opacity:v.opacity,start:v.start,duration:v.duration});let title=label;if(v.magnitude&&!title){title=M.layer('text','Magnitude label',{x:80,y:70,w:1000,h:90,fontSize:56,group,animation:'none'});project.layers.unshift(title);rings.magnitudeId=title.id;}if(title)Object.assign(title,{text:v.magnitude,start:v.start,duration:v.duration,visible:!!v.magnitude,color:v.color});project.duration=Math.max(project.duration,v.start+v.duration);selected=new Set([rings.id]);time=v.start+Math.min(.8,v.duration/2);refresh();status('Earthquake added: rings, marker, and magnitude remain individually editable.');});}
